package com.bank.core;

import java.util.*;
import java.util.logging.*;

public class NullUnboxDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Case 1: absent map value unboxed
        Map<String, Integer> pending = new HashMap<>();
        pending.put("SAV2001", 3); // Rajesh has 3; Priya has no entry
        try {
            int priyaCount = pending.get("CUR3001"); // get → null → unbox → NPE
            log.info(() -> "Priya pending = " + priyaCount);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Case 1: unboxing absent map value threw NPE", e);
        }
        int safe1 = pending.getOrDefault("CUR3001", 0); // FIX
        log.info(() -> "Case 1 fix (getOrDefault): Priya pending = " + safe1);

        // Case 2: wrapper array element defaults to null (not 0)
        Integer[] monthlyCounts = new Integer[3]; // all elements null
        try {
            int firstMonth = monthlyCounts[0]; // null → unbox → NPE
            log.info(() -> "First month count = " + firstMonth);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Case 2: unboxing null wrapper array element threw NPE", e);
        }
        int[] primitiveCounts = new int[3]; // FIX: primitive array defaults to 0
        log.info(() -> "Case 2 fix (int[] defaults to 0): first month = " + primitiveCounts[0]);

        // Case 3: method declared to return int returns a null wrapper
        try {
            int rajesh = fetchCountReturningPrimitive("SAV2001", pending); // 3, fine
            int priya  = fetchCountReturningPrimitive("CUR3001", pending); // null → NPE at return
            log.info(() -> "Rajesh=" + rajesh + " Priya=" + priya);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Case 3: method returning primitive unboxed null", e);
        }
        int safe3 = fetchCountSafe("CUR3001", pending); // FIX: returns primitive with default
        log.info(() -> "Case 3 fix (safe method): Priya pending = " + safe3);

        // Case 4: null wrapper in arithmetic / comparison
        Integer nullable = pending.get("CUR3001"); // null
        try {
            if (nullable < 5) { // relational op unboxes → NPE
                log.info("branch taken");
            }
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Case 4: comparison on null wrapper unboxed → NPE", e);
        }
        boolean safe4 = nullable != null && nullable < 5; // FIX: null-check first
        log.info(() -> "Case 4 fix (null-check first): " + safe4);
    }

    // BAD: declared primitive return but body can produce null → unboxes at return
    static int fetchCountReturningPrimitive(String id, Map<String, Integer> m) {
        return m.get(id); // if absent, null → unbox → NPE
    }

    // GOOD: explicit default, never unboxes null
    static int fetchCountSafe(String id, Map<String, Integer> m) {
        Integer v = m.get(id);
        return v != null ? v : 0;
    }
}
